"use strict";
const assert = require("node:assert/strict");
const { freshState, validateState, growth, saleTotal, actOnPlot, parseYouTube } = require("./game.js");
const state = freshState(), now = Date.now();
actOnPlot(state, 0, now);
assert.equal(state.coins, 92);
assert.equal(state.plots[0].wateredAt, null);
assert.equal(growth(state.plots[0], now + 100000), 0, "Unwatered crops must not grow");
actOnPlot(state, 0, now);
assert.equal(growth(state.plots[0], now + 10000), 0.5);
actOnPlot(state, 0, now + 19999);
assert.equal(state.inventory.carrot, 0, "Early harvest must not give produce");
actOnPlot(state, 0, now + 20000);
assert.equal(state.inventory.carrot, 1);
assert.equal(state.plots[0], null);
assert.equal(state.xp, 10);
assert.equal(saleTotal(state), 15);
actOnPlot(state, 7, now);
assert.equal(state.unlocked, 6, "Unlocking must be sequential");
actOnPlot(state, 6, now);
assert.equal(state.unlocked, 7);
assert.equal(state.coins, 52);
state.coins = 0; state.freeSeeds = 3;
actOnPlot(state, 1, now);
assert.equal(state.coins, 0);
assert.equal(state.freeSeeds, 2);
assert.equal(state.plots[1].crop, "carrot");
const restored = validateState(JSON.parse(JSON.stringify(state)));
assert.ok(restored);
assert.equal(growth(restored.plots[1], now + 500000), 0);
restored.plots[1].wateredAt = now - 100000;
assert.equal(growth(restored.plots[1], now), 1, "Offline timestamp should make crops ripe");
assert.equal(validateState({ ...state, coins: -1 }), null);
assert.equal(validateState({ ...state, plots: [] }), null);
assert.equal(validateState({ ...state, selected: "__proto__" }), null);
for (const link of ["https://youtu.be/dQw4w9WgXcQ", "https://www.youtube.com/watch?v=dQw4w9WgXcQ", "https://youtube.com/shorts/dQw4w9WgXcQ", "https://m.youtube.com/embed/dQw4w9WgXcQ", "https://youtube.com/playlist?list=PLabcdefghijk12345"]) assert.match(parseYouTube(link).embed, /^https:\/\/www\.youtube\.com\/embed\//);
for (const link of ["https://youtube.com.evil.test/watch?v=dQw4w9WgXcQ", "https://evil.test/?v=dQw4w9WgXcQ", "javascript:alert(1)", "https://youtube.com/watch?v=bad", "https://user@youtube.com/watch?v=dQw4w9WgXcQ", "https://youtube.com/watch?v=dQw4w9WgXcQ&list=%3Cscript%3E", "http://youtu.be/dQw4w9WgXcQ"]) assert.throws(() => parseYouTube(link));
console.log("Passed: planting, watering, growth, harvest, inventory, expansion, free seeds, offline restore, corrupt saves, and safe YouTube parsing.");

